```
@mock_cloudformation
def test_creation(cloudformation):

  template_body = '''{
      "AWSTemplateFormatVersion": "2010-09-09",
      "Resources": {
          "MyBucket": {
              "Type": "AWS::S3::Bucket",
              "Properties": {
                  "BucketName": "my-bucket"
              }
          }
      }
